// Protocol model follows
// https://sites.google.com/view/astro-gadget/control-of-focusers/focusdreampro
// and https://github.com/sirJolo/ascom-jolo-focuser. Commands carry no
// terminator; the controller parses a request once the bytes stop arriving.

#define _DEFAULT_SOURCE
#define _XOPEN_SOURCE 600

#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "../../../indigo_test/simulator_common/serial_simulator_common.h"
#include "../../../indigo_test/simulator_common/serial_motion.h"

#define COMMAND_LENGTH 32

typedef struct {
	bool headless;
	bool trace;
	const char *ready_file;
} simulator_options;

static simulator_options options = {
	.headless = false,
	.trace = true,
	.ready_file = NULL
};

static const char *simulator_name = "focuser_focusdreampro";
// normal            - FocusDreamPro with a temperature probe
// jolo              - Astrojolo controller, otherwise identical
// no-temperature    - controller without a probe, answers T:false
// no-identity       - silent controller, the # transaction times out
// temperature-error - identity works, every T reply is malformed
// move-error        - M: and R: are rejected instead of echoed
// abort-error       - H is rejected instead of echoed
static const char *profile = "normal";
static volatile sig_atomic_t running = 1;
static int serial_fd = -1;
static serial_motion motion;
static int max_position = 1000000;
// The controller's S: value is a per step delay in microseconds.
static int step_delay = 500;
static int duty_cycle = 20;
static double temperature = 21.5;

static void usage(const char *name) {
	printf("AstroGadget FocusDreamPro serial simulator\n");
	printf("Usage: %s [OPTIONS]\n", name);
	printf("  --headless              Disable terminal-oriented output\n");
	printf("  --ready-file <path>     Write INDIGO_SIMULATOR_PORT after PTY setup\n");
	printf("  --trace                 Log protocol requests and replies\n");
	printf("  --profile <name>        normal, jolo, no-temperature, no-identity,\n");
	printf("                          temperature-error, move-error or abort-error\n");
	printf("  -h, --help              Show this help and exit\n");
}

static void signal_handler(int sig) {
	(void)sig;
	running = 0;
	if (serial_fd >= 0) {
		close(serial_fd);
		serial_fd = -1;
	}
}

static bool parse_args(int argc, char *argv[]) {
	for (int i = 1; i < argc; i++) {
		if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
			usage(argv[0]);
			exit(0);
		} else if (!strcmp(argv[i], "--headless")) {
			options.headless = true;
			options.trace = false;
		} else if (!strcmp(argv[i], "--trace")) {
			options.trace = true;
		} else if (!strcmp(argv[i], "--ready-file")) {
			if (++i == argc) {
				fprintf(stderr, "--ready-file requires a path\n");
				return false;
			}
			options.ready_file = argv[i];
		} else if (!strcmp(argv[i], "--profile")) {
			if (++i == argc) {
				fprintf(stderr, "--profile requires a name\n");
				return false;
			}
			profile = argv[i];
		} else {
			fprintf(stderr, "Unknown option '%s'\n", argv[i]);
			return false;
		}
	}
	return true;
}

static int clamp_position(int value) {
	if (value < 0) {
		return 0;
	}
	if (value > max_position) {
		return max_position;
	}
	return value;
}

static void send_line(const char *line) {
	serial_simulator_trace_line(options.trace, "->", line);
	serial_simulator_write_all(serial_fd, line, strlen(line));
	serial_simulator_write_all(serial_fd, "\n", 1);
}

static void handle_command(const char *command) {
	char response[COMMAND_LENGTH] = { 0 };
	serial_simulator_trace_line(options.trace, "<-", command);
	if (!strcmp(command, "#")) {
		if (!strcmp(profile, "no-identity")) {
			return;
		}
		send_line(!strcmp(profile, "jolo") ? "Jolo 1.0" : "FD");
	} else if (!strcmp(command, "T")) {
		if (!strcmp(profile, "no-temperature")) {
			send_line("T:false");
		} else if (!strcmp(profile, "temperature-error")) {
			send_line("ERR");
		} else {
			snprintf(response, sizeof(response), "T:%.1f", temperature);
			send_line(response);
		}
	} else if (!strcmp(command, "I")) {
		serial_motion_update(&motion);
		send_line(motion.duration > 0 ? "I:true" : "I:false");
	} else if (!strcmp(command, "P")) {
		snprintf(response, sizeof(response), "P:%d", (int)serial_motion_update(&motion));
		send_line(response);
	} else if (!strncmp(command, "X:", 2)) {
		max_position = atoi(command + 2);
		if (max_position < 0) {
			max_position = 0;
		}
		serial_motion_sync(&motion, clamp_position((int)serial_motion_update(&motion)));
		send_line(command);
	} else if (!strncmp(command, "S:", 2)) {
		step_delay = atoi(command + 2);
		if (step_delay < 1) {
			step_delay = 1;
		}
		send_line(command);
	} else if (!strncmp(command, "D:", 2)) {
		duty_cycle = atoi(command + 2);
		(void)duty_cycle;
		send_line(command);
	} else if (!strncmp(command, "M:", 2)) {
		if (!strcmp(profile, "move-error")) {
			send_line("ERR");
			return;
		}
		serial_motion_start(&motion, clamp_position(atoi(command + 2)), 1000000.0 / step_delay);
		send_line(command);
	} else if (!strncmp(command, "R:", 2)) {
		if (!strcmp(profile, "move-error")) {
			send_line("ERR");
			return;
		}
		serial_motion_sync(&motion, clamp_position(atoi(command + 2)));
		send_line(command);
	} else if (!strcmp(command, "H")) {
		serial_motion_stop(&motion);
		send_line(!strcmp(profile, "abort-error") ? "ERR" : "H");
	}
}

static void run_protocol_loop(void) {
	char buffer[COMMAND_LENGTH] = { 0 };
	size_t length = 0;
	while (running) {
		char c = '\0';
		ssize_t bytes_read = read(serial_fd, &c, 1);
		if (bytes_read < 0) {
			if (errno == EINTR) {
				continue;
			}
			if (errno == EAGAIN || errno == EWOULDBLOCK || errno == EIO) {
				// The protocol has no request terminator, so a gap in the
				// incoming bytes ends the command.
				if (length > 0) {
					buffer[length] = '\0';
					handle_command(buffer);
					length = 0;
					buffer[0] = '\0';
				}
				usleep(1000);
				continue;
			}
			perror("read");
			break;
		}
		if (bytes_read == 0) {
			continue;
		}
		if (c == '\r' || c == '\n') {
			continue;
		}
		if (length < sizeof(buffer) - 1) {
			buffer[length++] = c;
		} else {
			length = 0;
			buffer[0] = '\0';
		}
	}
}

int main(int argc, char *argv[]) {
	char port[256] = { 0 };
	if (!parse_args(argc, argv)) {
		return 1;
	}
	signal(SIGTERM, signal_handler);
	signal(SIGINT, signal_handler);
	serial_motion_sync(&motion, 0);
	serial_fd = serial_simulator_open_pty(port, sizeof(port));
	if (serial_fd < 0) {
		return 1;
	}
	if (options.ready_file != NULL && !serial_simulator_write_ready_file(options.ready_file, simulator_name, port)) {
		close(serial_fd);
		return 1;
	}
	if (!options.headless) {
		printf("AstroGadget FocusDreamPro simulator ready on %s\n", port);
	}
	run_protocol_loop();
	if (serial_fd >= 0) {
		close(serial_fd);
	}
	return 0;
}
